// ===== Fault-tolerant JSON parse helper (pasted into every Code node) =====
function tryParse(s) { try { return JSON.parse(s); } catch (e) { return null; } }

function salvageArray(t, key) {
  const k = t.indexOf('"' + key + '"');
  if (k < 0) return [];
  let i = t.indexOf('[', k);
  if (i < 0) return [];
  i++;
  const out = [];
  let depth = 0, inStr = false, esc = false, start = -1;
  for (; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === '{') { if (depth === 0) start = i; depth++; }
    else if (c === '}') {
      depth--;
      if (depth === 0 && start >= 0) {
        const o = tryParse(t.slice(start, i + 1));
        if (o) out.push(o);
        start = -1;
      }
    } else if (c === ']' && depth === 0) break;
  }
  return out;
}

// Return the end index (inclusive) of the balanced {...} starting at `from`, or -1 if never closed (truncated).
function balancedEnd(t, from) {
  let depth = 0, inStr = false, esc = false;
  for (let i = from; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') inStr = true;
    else if (c === '{') depth++;
    else if (c === '}') { depth--; if (depth === 0) return i; }
  }
  return -1;
}

// Returns { data, salvaged } or null.
// Handles: model "thinking out loud" before the JSON, ```json fences, <think> blocks, trailing commas,
// smart quotes, and JSON truncated by the token limit (salvages the complete elements of arrayKey).
function parseLoose(raw, arrayKey) {
  let t = String(raw || '')
    .replace(/<think>[\s\S]*?<\/think>/gi, '')
    .replace(/```json/gi, '').replace(/```/g, '').trim();

  // Candidate starts: every "{" followed by a quoted key. Prefer the ones whose first key is a known key.
  const known = /^\{\s*"(features|requirements|results|conditions|coverage_items|chunk_id|muc_tieu_tai_lieu)"/;
  const starts = [];
  const re = /\{\s*"/g;
  let m;
  while ((m = re.exec(t)) !== null) starts.push(m.index);
  starts.sort((a, b) => (known.test(t.slice(b)) ? 1 : 0) - (known.test(t.slice(a)) ? 1 : 0) || a - b);
  const ordered = starts.filter(s => known.test(t.slice(s))).concat(starts.filter(s => !known.test(t.slice(s))));

  const fixes = s => [
    s,
    s.replace(/,\s*([}\]])/g, '$1'),
    s.replace(/[“”]/g, '"').replace(/[‘’]/g, "'").replace(/,\s*([}\]])/g, '$1')
  ];

  for (const st of ordered.slice(0, 40)) {
    const end = balancedEnd(t, st);
    if (end < 0) continue;
    for (const s of fixes(t.slice(st, end + 1))) {
      const p = tryParse(s);
      if (p && typeof p === 'object' && !Array.isArray(p)) {
        if (!arrayKey || Array.isArray(p[arrayKey]) || ordered.length === 1) return { data: p, salvaged: false };
      }
    }
  }

  // Truncated output: salvage complete elements of arrayKey from the best candidate
  if (arrayKey) {
    for (const st of ordered) {
      const tail = t.slice(st);
      if (tail.indexOf('"' + arrayKey + '"') < 0) continue;
      const items = salvageArray(tail, arrayKey);
      if (items.length) {
        const mm = tail.match(/"(?:chunk_id|condition_id)"\s*:\s*"([^"]+)"/);
        const data = { [arrayKey]: items };
        if (mm) data[tail.indexOf('"chunk_id"') >= 0 ? 'chunk_id' : 'condition_id'] = mm[1];
        return { data, salvaged: true };
      }
    }
  }
  return null;
}

// Chuẩn hóa test case do AI sinh cho 1 BATCH condition; gắn metadata từ condition (không tin AI); không để rơi condition/phân vùng nào.
function processOne(first, batchArg) {
const aiText = first.output || first.text || '';
const arrOf = v => (Array.isArray(v) ? v : v ? [v] : []);

const parsed = String(aiText).trim() ? parseLoose(aiText, 'results') : null;
let results = parsed && Array.isArray(parsed.data.results) ? parsed.data.results : [];
// tương thích ngược: AI trả 1 object {condition_id, testcases} thay vì {results:[...]}
if (!results.length && parsed && Array.isArray(parsed.data.testcases)) results = [parsed.data];

// Tra cứu condition + suite_order từ Parse_conditions
const condMap = new Map();
try {
  for (const it of $('Parse_conditions').all()) {
    for (const c of arrOf(it.json.conditions)) condMap.set(c.condition_id, { cond: c, order: it.json.suite_order });
  }
} catch (e) { /* bỏ qua */ }

// Conditions of this batch are passed in by processOne(first, batchArg)
let batch = arrOf(batchArg);

let targets = batch.length ? batch : results.map(r => (condMap.get(r.condition_id) || {}).cond || { condition_id: r.condition_id || '', test_suite: 'General', test_technique: '', condition_type: '', requirement_ids: [] });
if (!targets.length) {
  throw new Error('AI_Phan_tich_Testcase trả JSON không hợp lệ và không xác định được condition.\nRAW:\n' + String(aiText).slice(0, 3000));
}
const resById = new Map(results.map(r => [r.condition_id, r]));

function toList(value) {
  if (value === null || value === undefined) return [];
  const a = Array.isArray(value) ? value : String(value).split('\n');
  return a.map(x => String(x === null || x === undefined ? '' : x).trim().replace(/^\d+\s*[\.\)]\s*/, '')).filter(x => x !== '');
}
function buildSteps(pre, steps) {
  // Định dạng giống checklist mẫu: "Pre: \n1. ...\nStep: \n1. ..."
  const numbered = list => list.map((x, i) => (i + 1) + '. ' + x).join('\n');
  const p = toList(pre), s = toList(steps);
  if (p.length === 0) return 'Step:\n' + numbered(s);
  return 'Pre: \n' + numbered(p) + '\nStep: \n' + numbered(s);
}
function formatResult(v) {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.filter(x => x !== null && x !== undefined && String(x).trim() !== '').map(x => String(x).trim()).join('\n\n');
  return String(v).trim();
}
const startsOk = s => /^(Kiểm tra|Xác minh|Validate)\b/i.test(s);

function fallbackTC(cond, label) {
  const steps = ['Đăng nhập thành công', 'Truy cập chức năng thuộc "' + (cond.test_suite || '') + '"']
    .concat(arrOf(label ? [label] : cond.test_data_hint).map(h => 'Chuẩn bị/nhập dữ liệu: ' + h))
    .concat(cond.context ? ['Thực hiện thao tác theo ngữ cảnh: ' + cond.context] : [])
    .concat(['Quan sát và đối chiếu kết quả mong muốn']);
  const exp = arrOf(cond.expected_behavior_hint);
  const lines = exp.length ? exp.join('\n- ') : 'N/A (Tài liệu chưa đặc tả)';
  return {
    test_suite: cond.test_suite,
    muc_dich: 'Kiểm tra ' + (cond.condition || '') + (label ? ' - ' + label : ''),
    dieu_kien_tien_quyet: cond.preconditions || [],
    cac_buoc: steps,
    ket_qua_mong_muon: [steps.length + '. - ' + lines],
    _fallback: true
  };
}

function buildRows(cond, r) {
  let tcs = r && Array.isArray(r.testcases) ? r.testcases : [];
  const plan = r && Array.isArray(r.phan_vung_ap_dung) ? r.phan_vung_ap_dung : [];
  const notes = [];
  if (!tcs.length) notes.push(parsed && parsed.salvaged ? 'JSON test case bị cắt cụt, condition này chưa được AI sinh' : 'AI không trả test case hợp lệ cho condition này');

  // Condition/phân vùng chưa có TC -> sinh TC dự phòng để không rơi coverage
  if (!tcs.length) {
    const labels = plan.length ? plan : arrOf(cond.test_data_hint);
    tcs = labels.length ? labels.map(l => fallbackTC(cond, l)) : [fallbackTC(cond, '')];
  } else if (plan.length > tcs.length) {
    notes.push('AI lập kế hoạch ' + plan.length + ' phân vùng nhưng chỉ sinh ' + tcs.length + ' TC');
    for (let i = tcs.length; i < plan.length; i++) tcs.push(fallbackTC(cond, plan[i]));
  }

  const ctxOrder = (condMap.get(cond.condition_id) || {}).order;
  const order = cond.suite_order !== undefined ? cond.suite_order : (ctxOrder !== undefined ? ctxOrder : 9999);
  const srcRef = arrOf(cond.requirement_ids).join(', ');
  const tag = srcRef ? '[Nguồn: ' + srcRef + ']' : '';
  const gapNote = cond.requirement_gap ? ' [Thiếu đặc tả: ' + cond.requirement_gap + ']' : '';

  return tcs.map(tc => {
    let purpose = String(tc.muc_dich || '').trim();
    if (purpose && !startsOk(purpose)) purpose = 'Kiểm tra ' + purpose.charAt(0).toLowerCase() + purpose.slice(1);
    const review = tc._fallback || cond._generated ? ' [CẦN RÀ SOÁT: ' + (notes.join('; ') || 'nội dung sinh dự phòng, chưa được AI chi tiết hóa') + ']' : '';
    return {
      json: {
        test_suite: cond.test_suite || tc.test_suite || 'General',
        suite_order: order,
        condition_id: cond.condition_id || '',
        muc_dich: purpose,
        cac_buoc: buildSteps(tc.dieu_kien_tien_quyet, tc.cac_buoc),
        ket_qua_mong_muon: formatResult(tc.ket_qua_mong_muon),
        ghi_chu: tag + gapNote + review
      }
    };
  });
}

const out = [];
for (const cond of targets) {
  const r = resById.get(cond.condition_id) || (targets.length === 1 && results.length === 1 ? results[0] : null);
  out.push(...buildRows(cond, r));
}
return out.filter(r => r.json.muc_dich && r.json.cac_buoc);
}

// AI node output is index-aligned with Make_batches (1 output item per batch, errors included)
const batches = $('Make_batches').all();
const all = [];
$input.all().forEach((it, idx) => {
  const b = batches[idx] ? batches[idx].json.conditions : [];
  all.push(...processOne(it.json, b));
});
return all;

// Lấy data từ API Figma trả về
const figmaData = $input.first().json;
const documentNode = figmaData.document;

// Lấy thông tin bài toán cũ truyền sang để không bị mất kết nối
const baiToanGoc = $("Update_link_sheet_TC").first().json; 

// Đệ quy moi móc toàn bộ Text trên giao diện
function extractText(node) {
    let texts = [];
    if (node.type === "TEXT" && node.characters) {
        texts.push(`[${node.name}]: ${node.characters.replace(/\n/g, ' ')}`); 
    }
    if (node.children) {
        for (let child of node.children) {
            texts = texts.concat(extractText(child));
        }
    }
    return texts;
}

const allExtractedText = extractText(documentNode);

// Trả về biến 'data' giống hệt định dạng của nhánh Google Docs
return {
    json: {
        ...baiToanGoc, // Giữ lại tên Bài toán, Link Testcase...
        "data": "DỮ LIỆU GIAO DIỆN TỪ FIGMA:\n" + allExtractedText.join("\n")
    }
};

// 1. Lấy toàn bộ dữ liệu từ node trước đó (nhánh "Chưa làm")
const items = $input.all();
const newItems = [];

// 2. Duyệt qua từng bài toán
for (let i = 0; i < items.length; i++) {
    const item = items[i].json;
    const rawUrls = item["URL"] || "";

    // 3. Tách link: Xử lý cắt chuỗi bằng dấu phẩy (,) hoặc dấu xuống dòng (\n)
    const urlArray = rawUrls.split(/[,\n]+/);

    // 4. Tạo ra các item lẻ cho từng link để node sau dễ đọc
    for (let j = 0; j < urlArray.length; j++) {
        const singleUrl = urlArray[j].trim();

        // Nếu link không bị rỗng thì mới đẩy vào mảng
        if (singleUrl !== "") {
            newItems.push({
                json: {
                    ...item,             // Giữ lại toàn bộ data cũ (Tên bài toán, Link Testcase...)
                    "url_le": singleUrl  // Tạo thêm 1 trường mới chỉ chứa 1 link duy nhất để đọc
                }
            });
        }
    }
}

// 5. Trả về danh sách các link lẻ đã được tách
return newItems;

const items = $input.all();
const grouped = {};

// Dọn rác khoảng trắng: tài liệu Word/Docs crawl về chứa hàng chục nghìn ký tự \r \n \t lặp lại
// -> phình số token khiến AI bị "Request timed out". Làm sạch trước khi gom/lưu/gửi AI.
function cleanDoc(s) {
  return String(s || '')
    .replace(/\r\n?/g, '\n')
    .replace(/\u00a0/g, ' ')
    .split('\n')
    .map(l => l.replace(/[ \t]+/g, ' ').trim())
    .join('\n')
    .replace(/\n{2,}/g, '\n')   // bỏ toàn bộ dòng trống thừa
    .trim();
}

items.forEach(item => {
    const json = item.json;
    const key = json['Bài toán'] || 'Default'; // Gom nhóm theo Tên bài toán

    if (!grouped[key]) {
        grouped[key] = { ...json, data: [] };
    }

    const txt = cleanDoc(json.data);
    if (txt) grouped[key].data.push(txt);
});

const results = [];
for (const key in grouped) {
    const finalItem = grouped[key];
    finalItem.data = finalItem.data.join("\n\n--- TÀI LIỆU TIẾP THEO ---\n\n");
    results.push({ json: finalItem });
}

return results;

const items = $input.all();
const baiToanGoc = items[0].json; 

let textContent = `\n\n--- DANH SÁCH API CẦN KIỂM THỬ (BẮT BUỘC ĐỌC) ---\n`;

items.forEach((item) => {
    const data = item.json;
    // Bắt đúng các key từ file Google Sheets của anh
    const tenApi = data["Danh sách api sử dụng "] || "";
    const endpoint = data["col_3"] || data["Đầu api"] || "";
    const moTa = data["col_4"] || data["Mô tả"] || "";

    // Chỉ lấy những dòng có chứa đường link http/api
    if (endpoint.includes("http") || endpoint.includes("api/")) {
        textContent += `\n* Tên API: ${tenApi}\n  - Endpoint: ${endpoint}\n  - Mô tả bổ sung: ${moTa}\n`;
    }
});

return {
    json: {
        "Bài toán": baiToanGoc["Bài toán"],
        "Link Testcase": baiToanGoc["Link Testcase"],
        "Trạng thái": baiToanGoc["Trạng thái"],
        "url_le": baiToanGoc["url_le"],
        "data": textContent
    }
};

// Lấy JSON phân tích từ output AI, kể cả khi model "nghĩ thành tiếng" trước JSON, có dấu ngoặc kép chưa escape, hoặc JSON bị cắt cụt.
const ai = $('AI_phan_tich_bai_toan').first().json;
const raw = String(ai.output || ai.text || '');

const SECTIONS = [
  ['muc_tieu_tai_lieu', '1. MỤC TIÊU TÀI LIỆU'],
  ['he_thong_va_api', '2. CÁC HỆ THỐNG VÀ API'],
  ['luong_nghiep_vu', '3. LUỒNG NGHIỆP VỤ CHÍNH'],
  ['bang_du_lieu', '4. CÁC BẢNG DỮ LIỆU'],
  ['test_scenarios', '5. KỊCH BẢN KIỂM THỬ (TEST SCENARIOS)'],
  ['rui_ro_va_cau_hoi', '6. RỦI RO / ĐIỂM CHƯA RÕ']
];

function tryParse(s) { try { return JSON.parse(s); } catch (e) { return null; } }

function balancedEnd(t, from) {
  let depth = 0, inStr = false, esc = false;
  for (let i = from; i < t.length; i++) {
    const c = t[i];
    if (inStr) { if (esc) esc = false; else if (c === '\\') esc = true; else if (c === '"') inStr = false; continue; }
    if (c === '"') inStr = true;
    else if (c === '{') depth++;
    else if (c === '}') { depth--; if (depth === 0) return i; }
  }
  return -1;
}

function unescape(s) {
  const p = tryParse('"' + s.replace(/\n/g, '\\n') + '"');
  return p !== null ? p : s.replace(/\\n/g, '\n').replace(/\\"/g, '"').replace(/\\\\/g, '\\');
}

// Đọc 1 chuỗi JSON bắt đầu sau dấu " mở; tự động xử lý cả trường hợp AI quên escape dấu " bên trong câu tiếng Việt
function readLooseString(t, i) {
  let s = '', esc = false;
  for (; i < t.length; i++) {
    const c = t[i];
    if (esc) { s += '\\' + c; esc = false; continue; }
    if (c === '\\') { esc = true; continue; }
    if (c === '"') {
      // Kiểm tra xem dấu " này có thực sự là kết thúc chuỗi JSON không (theo sau bởi , ] } hoặc xuống dòng + khoảng trắng rồi , ] })
      const rest = t.slice(i + 1);
      if (/^\s*(?:,|\]|\}|$)/.test(rest)) {
        return { value: unescape(s), nextIdx: i + 1, closed: true };
      }
      // Nếu không phải kết thúc chuỗi JSON -> đây là dấu " chưa được escape nằm giữa câu!
      s += '"';
      continue;
    }
    s += c;
  }
  return { value: unescape(s), nextIdx: t.length, closed: false };
}

// Đọc mảng các chuỗi JSON: "key": [ "item 1", "item 2", ... ] kể cả khi mảng bị cắt cụt hoặc chứa dấu " chưa escape
function readLooseArray(t, openBracketIdx, nextKeyPositions) {
  let limit = t.length;
  for (const pos of nextKeyPositions) {
    if (pos > openBracketIdx && pos < limit) limit = pos;
  }
  const sub = t.slice(openBracketIdx + 1, limit);
  const items = [];
  let closed = false;
  let i = 0;
  while (i < sub.length) {
    while (i < sub.length && /[\s,]/.test(sub[i])) i++;
    if (i >= sub.length) break;
    if (sub[i] === ']') { closed = true; break; }
    if (sub[i] === '"') {
      const r = readLooseString(sub, i + 1);
      if (r.value.trim()) items.push('- ' + r.value.trim().replace(/^[-*•]\s*/, ''));
      i = r.nextIdx;
      if (!r.closed) { closed = false; break; }
    } else if (sub[i] === '{') {
      const endObj = balancedEnd(sub, i);
      if (endObj > i) {
        const objStr = sub.slice(i, endObj + 1);
        const parsedObj = tryParse(objStr);
        if (parsedObj && typeof parsedObj === 'object') {
          items.push('- ' + Object.values(parsedObj).filter(Boolean).join(': '));
        } else {
          items.push('- ' + objStr);
        }
        i = endObj + 1;
      } else {
        break;
      }
    } else {
      i++;
    }
  }
  return { items, closed };
}

const asText = v => (Array.isArray(v)
  ? v.map(x => {
      const line = typeof x === 'string' ? x.trim() : JSON.stringify(x);
      return line.startsWith('-') || line.startsWith('*') ? line : '- ' + line;
    }).join('\n')
  : (v !== null && typeof v === 'object') ? JSON.stringify(v, null, 1) : String(v));

const t = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/```json/gi, '').replace(/```/g, '');

// 1. Tìm object JSON hoàn chỉnh (ưu tiên bản xuất hiện CUỐI)
let data = null, truncated = false;
const starts = [];
const re = /\{\s*"(muc_tieu_tai_lieu|he_thong_va_api|luong_nghiep_vu|bang_du_lieu|test_scenarios|rui_ro_va_cau_hoi)"/g;
let m;
while ((m = re.exec(t)) !== null) starts.push(m.index);
for (const st of starts.slice().reverse()) {
  const end = balancedEnd(t, st);
  if (end < 0) continue;
  const s = t.slice(st, end + 1);
  const p = tryParse(s) || tryParse(s.replace(/,\s*([}\]])/g, '$1'));
  if (p && typeof p === 'object') { data = p; break; }
}

// 2. Nếu JSON.parse thất bại (do bị cắt cụt token hoặc AI quên escape dấu " trong chuỗi):
// Cứu từng mục cho CẢ kiểu mảng ("key": [ ... ]) LẪN kiểu chuỗi ("key": "...")
if (!data) {
  data = {};
  const workingText = starts.length ? t.slice(starts[starts.length - 1]) : t;

  const keyPositions = [];
  for (const [k] of SECTIONS) {
    const km = [...workingText.matchAll(new RegExp('"' + k + '"\\s*:', 'g'))].pop();
    if (km) keyPositions.push(km.index);
  }

  for (const [key] of SECTIONS) {
    const km = [...workingText.matchAll(new RegExp('"' + key + '"\\s*:\\s*([\\["])', 'g'))].pop();
    if (!km) continue;
    const openChar = km[1];
    const openIdx = km.index + km[0].length - 1;

    if (openChar === '"') {
      const r = readLooseString(workingText, openIdx + 1);
      if (r.value.trim()) {
        data[key] = r.value.trim() + (r.closed ? '' : '\n[... nội dung bị cắt cụt do hết giới hạn token]');
        if (!r.closed) truncated = true;
      }
    } else if (openChar === '[') {
      const r = readLooseArray(workingText, openIdx, keyPositions);
      if (r.items.length) {
        data[key] = r.items.join('\n') + (r.closed ? '' : '\n[... danh sách bị cắt cụt do hết giới hạn token]');
        if (!r.closed) truncated = true;
      }
    }
  }
  if (!Object.keys(data).length) data = null;
}

let combinedText = '';
if (data) {
  for (const [key, title] of SECTIONS) {
    if (data[key] !== undefined && data[key] !== null && String(data[key]).trim() !== '') {
      combinedText += title + '\n' + asText(data[key]).trim() + '\n\n';
    }
  }
  if (truncated) combinedText += '(Lưu ý: kết quả AI dài vượt giới hạn token nên một số ý cuối cùng có thể bị lược bớt.)\n';
  if (!combinedText) for (const k in data) combinedText += k.toUpperCase() + ':\n' + asText(data[k]) + '\n\n';
} else {
  combinedText = 'Nội dung phân tích (AI không trả JSON hợp lệ):\n\n' + raw.trim();
}

