// ===== Helpers =====
function tryParse(s) { try { return JSON.parse(s); } catch (e) { return null; } }
const fixComma = s => s.replace(/,\s*([}\]])/g, '$1');

// Cứu các phần tử {...} hoàn chỉnh của mảng `key` trong chuỗi JSON (kể cả khi bị cắt cụt)
function salvageArray(t, key) {
  const k = t.indexOf('"' + key + '"');
  if (k < 0) return [];
  let i = t.indexOf('[', k);
  if (i < 0) return [];
  i++;
  const out = [];
  let depth = 0, inStr = false, esc = false, start = -1;
  for (; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === '{') { if (depth === 0) start = i; depth++; }
    else if (c === '}') {
      depth--;
      if (depth === 0 && start >= 0) {
        const o = tryParse(t.slice(start, i + 1));
        if (o) out.push(o);
        start = -1;
      }
    } else if (c === ']' && depth === 0) break;
  }
  return out;
}

// Trả về vị trí kết thúc (inclusive) của {...} cân bằng bắt đầu tại `from`, hoặc -1 nếu bị cắt cụt
function balancedEnd(t, from) {
  let depth = 0, inStr = false, esc = false;
  for (let i = from; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') inStr = true;
    else if (c === '{') depth++;
    else if (c === '}') { depth--; if (depth === 0) return i; }
  }
  return -1;
}

// Vá JSON bị cắt cụt: trả về danh sách chuỗi ứng viên để thử parse
//  A: đóng chuỗi đang dở (nếu đang ở giá trị) rồi đóng các ngoặc còn thiếu
//  B: lùi về dấu phẩy gần nhất rồi đóng các ngoặc còn thiếu
function repairCandidates(t) {
  const stack = [];
  let inStr = false, esc = false, strStart = -1;
  let lastComma = -1, lastCommaStack = null;
  for (let i = 0; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; strStart = i; continue; }
    if (c === '{') stack.push('}');
    else if (c === '[') stack.push(']');
    else if (c === '}' || c === ']') { stack.pop(); if (!stack.length) return []; } // đã hoàn chỉnh
    else if (c === ',') { lastComma = i; lastCommaStack = stack.slice(); }
  }
  const cands = [];
  if (inStr && strStart > 0) {
    const before = t.slice(0, strStart).trimEnd();
    if (before.endsWith(':')) { // chuỗi đang dở là một GIÁ TRỊ
      let s = esc ? t.slice(0, -1) : t;
      cands.push(s + '"' + stack.slice().reverse().join(''));
    }
  }
  if (lastComma > 0 && lastCommaStack) {
    cands.push(t.slice(0, lastComma) + lastCommaStack.slice().reverse().join(''));
  }
  return cands;
}

// ===== Parser riêng cho bước trích requirement =====
// Bỏ phần "nghĩ thành tiếng", bỏ bản mẫu rỗng chép từ prompt, ưu tiên JSON hoàn chỉnh (bản CUỐI),
// nếu bị cắt cụt thì vá lại / cứu từng phần tử hoàn chỉnh.
function parseRequirements(raw) {
  const t = String(raw || '').replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/```json/gi, '').replace(/```/g, '');
  if (!t.trim()) return { fail: 'empty' };
  const hasReal = o => o && Array.isArray(o.requirements) &&
    o.requirements.some(r => r && String(r.requirement || '').trim());
  const starts = [];
  const re = /\{\s*"(?:features|requirements)"/g;
  let m;
  while ((m = re.exec(t)) !== null) starts.push(m.index);
  if (!starts.length) return { fail: 'no_json' };
  const rev = starts.slice().reverse();

  // 1. JSON hoàn chỉnh
  for (const st of rev) {
    const end = balancedEnd(t, st);
    if (end < 0) continue;
    const s = t.slice(st, end + 1);
    const p = tryParse(s) || tryParse(fixComma(s));
    if (hasReal(p)) return { data: p, salvaged: false };
  }

  // 2. JSON bị cắt cụt -> vá lại
  for (const st of rev) {
    for (const s of repairCandidates(t.slice(st))) {
      const p = tryParse(s) || tryParse(fixComma(s));
      if (hasReal(p)) return { data: p, salvaged: true };
    }
  }

  // 3. Dự phòng: cứu từng phần tử hoàn chỉnh
  for (const st of rev) {
    const tail = t.slice(st);
    const reqs = salvageArray(tail, 'requirements').filter(r => r && String(r.requirement || '').trim());
    if (!reqs.length) continue;
    const data = { requirements: reqs };
    ['features', 'business_rules', 'decision_tables', 'inputs', 'flows', 'apis', 'integrations',
     'data_objects', 'states', 'exceptions', 'ambiguities'].forEach(k => { data[k] = salvageArray(tail, k); });
    return { data, salvaged: true };
  }
  return { fail: 'no_requirement' };
}

// ===== Gộp kết quả của TẤT CẢ các chunk thành 1 object requirement duy nhất =====
const outItems = $input.all();
const parsed = [];
const warnings = [];
outItems.forEach((it, idx) => {
