});
if (!parsed.length) throw new Error('AI_structured_requirement: không chunk nào trả về JSON hợp lệ.\n' + warnings.join('\n'));

const arr = (o, k) => (o && Array.isArray(o[k]) ? o[k].filter(x => x && typeof x === 'object') : []);
