};
const featByName = new Map();   // gộp feature cùng tên giữa các chunk
const seen = { inputs: new Set(), apis: new Set(), data_objects: new Set(), states: new Set(), dependencies: new Set(), cs: new Set() };
let nFeat = 0, nReq = 0, nBR = 0, nDT = 0, nFlow = 0, nInt = 0, nExc = 0;

parsed.forEach(({ idx, d }) => {
  const featMap = {}, reqMap = {};

  arr(d, 'features').forEach((f, i) => {
    const key = low(f.feature_name) || ('__f' + idx + '_' + i);
    let nf = featByName.get(key);
