      nf = { ...f, feature_id: 'FEAT' + pad(++nFeat), _ord: idx * 1000 + (Number(f.flow_order) || i + 1) };
      featByName.set(key, nf); out.features.push(nf);
    }
    featMap[f.feature_id] = nf.feature_id;
  });
  const mapFeat = id => featMap[id] || id;

  arr(d, 'requirements').forEach(r => {
    if (!String(r.requirement || '').trim()) return; // bỏ requirement rỗng
    const nid = 'REQ' + pad(++nReq);
    reqMap[r.requirement_id] = nid;
    out.requirements.push({ ...r, requirement_id: nid, feature_id: mapFeat(r.feature_id) });
  });
  const mapReq = id => reqMap[id] || id;

  arr(d, 'business_rules').forEach(x => out.business_rules.push({ ...x, rule_id: 'BR' + pad(++nBR), requirement_id: mapReq(x.requirement_id) }));
  arr(d, 'decision_tables').forEach(x => out.decision_tables.push({ ...x, table_id: 'DT' + pad(++nDT), requirement_id: mapReq(x.requirement_id) }));
  arr(d, 'integrations').forEach(x => out.integrations.push({ ...x, integration_id: 'INT' + pad(++nInt), requirement_id: mapReq(x.requirement_id) }));
  arr(d, 'exceptions').forEach(x => out.exceptions.push({ ...x, exception_id: 'EXC' + pad(++nExc), requirement_id: mapReq(x.requirement_id) }));
  arr(d, 'flows').forEach(x => out.flows.push({ ...x, flow_id: 'FLOW' + pad(++nFlow), feature_id: mapFeat(x.feature_id) }));
  arr(d, 'ambiguities').forEach(x => out.ambiguities.push({ ...x, related_requirement_id: mapReq(x.related_requirement_id) }));

  const dedupe = (k, keyOf) => arr(d, k).forEach(x => {
    const key = keyOf(x); if (seen[k].has(key)) return; seen[k].add(key); out[k].push(x);
  });
  dedupe('inputs', x => low(x.name));
  dedupe('apis', x => low(x.name) + '|' + low(x.method));
  dedupe('data_objects', x => low(x.table_or_object) + '|' + low(x.field) + '|' + low(x.data_change));
  dedupe('states', x => low(x.entity) + '|' + low(x.state));
