// ===== Fault-tolerant JSON parse helper (pasted into every Code node) =====
function tryParse(s) { try { return JSON.parse(s); } catch (e) { return null; } }

function salvageArray(t, key) {
  const k = t.indexOf('"' + key + '"');
  if (k < 0) return [];
  let i = t.indexOf('[', k);
  if (i < 0) return [];
  i++;
  const out = [];
  let depth = 0, inStr = false, esc = false, start = -1;
  for (; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === '{') { if (depth === 0) start = i; depth++; }
    else if (c === '}') {
      depth--;
      if (depth === 0 && start >= 0) {
        const o = tryParse(t.slice(start, i + 1));
        if (o) out.push(o);
        start = -1;
      }
    } else if (c === ']' && depth === 0) break;
  }
  return out;
}

// Return the end index (inclusive) of the balanced {...} starting at `from`, or -1 if never closed (truncated).
function balancedEnd(t, from) {
  let depth = 0, inStr = false, esc = false;
  for (let i = from; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') inStr = true;
    else if (c === '{') depth++;
    else if (c === '}') { depth--; if (depth === 0) return i; }
  }
  return -1;
}

// Returns { data, salvaged } or null.
function parseLoose(raw, arrayKey) {
  let t = String(raw || '')
    .replace(/<think>[\s\S]*?<\/think>/gi, '')
    .replace(/```json/gi, '').replace(/```/g, '').trim();

  const known = /^\{\s*"(features|requirements|results|conditions|coverage_items|chunk_id|muc_tieu_tai_lieu)"/;
  const starts = [];
  const re = /\{\s*"/g;
  let m;
  while ((m = re.exec(t)) !== null) starts.push(m.index);
  starts.sort((a, b) => (known.test(t.slice(b)) ? 1 : 0) - (known.test(t.slice(a)) ? 1 : 0) || a - b);
  const ordered = starts.filter(s => known.test(t.slice(s))).concat(starts.filter(s => !known.test(t.slice(s))));

  const fixes = s => [
    s,
    s.replace(/,\s*([}\]])/g, '$1'),
    s.replace(/[“”]/g, '"').replace(/[‘’]/g, "'").replace(/,\s*([}\]])/g, '$1')
  ];

  for (const st of ordered.slice(0, 40)) {
    const end = balancedEnd(t, st);
    if (end < 0) continue;
    for (const s of fixes(t.slice(st, end + 1))) {
      const p = tryParse(s);
      if (p && typeof p === 'object' && !Array.isArray(p)) {
        if (!arrayKey || Array.isArray(p[arrayKey]) || ordered.length === 1) return { data: p, salvaged: false };
      }
    }
  }

  if (arrayKey) {
    for (const st of ordered) {
      const tail = t.slice(st);
      if (tail.indexOf('"' + arrayKey + '"') < 0) continue;
      const items = salvageArray(tail, arrayKey);
      if (items.length) {
        const mm = tail.match(/"(?:chunk_id|condition_id)"\s*:\s*"([^"]+)"/);
        const data = { [arrayKey]: items };
        if (mm) data[tail.indexOf('"chunk_id"') >= 0 ? 'chunk_id' : 'condition_id'] = mm[1];
        return { data, salvaged: true };
      }
    }
  }
  return null;
}

// Parse Test_condition_generator theo từng chunk của Split_By_Feature, chuẩn hóa, và BẢO ĐẢM mọi requirement đều có >= 1 condition.
const featChunks = $('Split_By_Feature').all().map(i => i.json);
const results = $input.all();
const arrOf = v => (Array.isArray(v) ? v : v ? [v] : []);
const low = x => String(x === null || x === undefined ? '' : x).toLowerCase().trim();
const fuzzy = (a, b) => a && b && a.length >= 2 && b.length >= 2 && (a.includes(b) || b.includes(a));
const anyFuzzy = (text, names) => names.some(n => fuzzy(low(text), n));
const flat = v => arrOf(v).map(low).filter(x => x.length >= 2);
function pick(list, textOf, names, cap) {
  if (!list.length) return [];
  const hit = names.length ? list.filter(x => anyFuzzy(textOf(x), names)) : [];
  if (hit.length) return hit;
  return list.length <= cap ? list : [];
}

function conditionFromRequirement(r, suiteName) {
  return {
    coverage_ids: [],
    requirement_ids: [r.requirement_id],
    test_suite: suiteName,
    condition: 'Kiểm tra ' + (r.requirement || ''),
    context: r.context || '',
    condition_type: 'Positive',
    test_technique: 'Use case',
    preconditions: arrOf(r.preconditions),
    test_data_hint: arrOf(r.validation),
    expected_behavior_hint: r.expected_behavior ? [r.expected_behavior] : [],
    verify_points: { ui: [], network_api: [], log: [], database: [] },
    related_api: arrOf(r.related_api),
    related_fields: arrOf(r.related_fields),
    related_state: arrOf(r.related_state),
    requirement_gap: 'Condition sinh dự phòng vì AI chưa bao phủ requirement này - cần rà soát/bổ sung',
    _generated: 'requirement_fallback'
  };
}

const out = [];
results.forEach((it, idx) => {
  const raw = it.json.output || it.json.text || '';
  let parsed = null;
  if (String(raw).trim()) parsed = parseLoose(raw, 'conditions');
  const chunk = (parsed && featChunks.find(c => c.chunk_id === parsed.data.chunk_id)) || featChunks[idx];
  if (!chunk) return;

  let conds = parsed && Array.isArray(parsed.data.conditions) ? parsed.data.conditions : [];
  const warnings = [];
  if (!conds.length) warnings.push('Test_condition_generator không trả dữ liệu hợp lệ -> sinh condition dự phòng từ requirement');
  else if (parsed.salvaged) warnings.push('JSON condition bị cắt cụt, đã cứu ' + conds.length + ' condition');

  const reqCtx = chunk.context || {};
  // Đảm bảo mọi requirement trong chunk đều có ít nhất 1 condition
  const coveredReqIds = new Set();
  conds.forEach(c => arrOf(c.requirement_ids).forEach(id => coveredReqIds.add(String(id || '').trim())));
  (reqCtx.requirements || []).forEach(r => {
    if (r.requirement_id && !coveredReqIds.has(r.requirement_id)) {
      conds.push(conditionFromRequirement(r, chunk.suite_name));
    }
  });

  const normalized = conds.map((c, i) => {
    const reqIds = arrOf(c.requirement_ids);
    const idSet = new Set(reqIds);
    const byReq = x => (idSet.size ? idSet.has(x.requirement_id) : true);
    const names = flat(c.related_fields).concat(flat(c.related_state));
    const cond = {
      ...c,
      condition_id: chunk.chunk_id + '_C' + String(i + 1).padStart(3, '0'),
      test_suite: chunk.suite_name,
      suite_order: chunk.suite_order,
      coverage_ids: arrOf(c.coverage_ids),
      requirement_ids: reqIds,
      condition_type: c.condition_type || 'Positive',
      test_technique: c.test_technique || 'Use case',
      preconditions: arrOf(c.preconditions),
      test_data_hint: arrOf(c.test_data_hint),
      expected_behavior_hint: arrOf(c.expected_behavior_hint),
      verify_points: Object.assign({ ui: [], network_api: [], log: [], database: [] }, c.verify_points || {}),
      requirement_gap: c.requirement_gap || null
    };
    const tech = String(cond.test_technique || '');
    const isDT = /quyết định/i.test(tech);
    const isInt = /tích hợp|negative|hồi quy/i.test(tech) || cond.condition_type === 'Regression';
    cond.requirement_context = {
      requirements: (reqCtx.requirements || []).filter(byReq).map(r => ({
        requirement_id: r.requirement_id, requirement: r.requirement,
        expected_behavior: r.expected_behavior, validation: r.validation, error_handling: r.error_handling
      })),
      business_rules: (reqCtx.business_rules || []).filter(byReq),
      decision_tables: isDT ? (reqCtx.decision_tables || []).filter(byReq) : [],
      integrations: isInt ? (reqCtx.integrations || []).filter(byReq) : [],
      exceptions: isInt ? (reqCtx.exceptions || []).filter(byReq) : [],
      inputs: pick(reqCtx.inputs || [], x => x.name, names, 6),
      data_objects: isInt ? pick(reqCtx.data_objects || [], x => (x.table_or_object || '') + ' ' + (x.field || ''), names, 6) : [],
      states: pick(reqCtx.states || [], x => (x.entity || '') + ' ' + (x.state || ''), names, 6),
      change_scope: /hồi quy/i.test(cond.test_technique) || cond.condition_type === 'Regression' ? reqCtx.change_scope : undefined
    };
    return cond;
  });

  out.push({
    json: {
      chunk_id: chunk.chunk_id,
      suite_name: chunk.suite_name,
      suite_order: chunk.suite_order,
      conditions: normalized,
      _warnings: warnings
    }
  });
});

if (!out.length) throw new Error('Test_condition_generator không trả về dữ liệu cho chunk nào.');
return out;

// Gom test case theo Test Suite, sắp xếp suite theo tiến trình nghiệp vụ (suite_order), loại TC trùng hệt nhau.
const items = $input.all();
if (items.length === 0) return [];

const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const seen = new Set();
const groups = new Map();
let seq = 0;

for (const item of items) {
  const tc = item.json;
  const suite = tc.test_suite && String(tc.test_suite).trim() ? String(tc.test_suite).trim() : 'General';
  const key = suite + '||' + norm(tc.muc_dich) + '||' + norm(tc.cac_buoc) + '||' + norm(tc.ket_qua_mong_muon);
  if (seen.has(key)) continue; // trùng hệt
  seen.add(key);
  if (!groups.has(suite)) groups.set(suite, { order: Number.isFinite(Number(tc.suite_order)) ? Number(tc.suite_order) : 9999, first: seq++, list: [] });
  groups.get(suite).list.push(tc);
}

const ordered = [...groups.entries()].sort((a, b) => (a[1].order - b[1].order) || (a[1].first - b[1].first));

const prefix = (() => { try { const b = $('When Executed by Another Workflow').first().json.body || {}; return String(b.maTestCase || b.ma_testcase || b.prefix || 'TC').replace(/[\[\]]/g, ''); } catch (e) { return 'TC'; } })();
let tcNo = 0;
const result = [];
for (const [suite, g] of ordered) {
  result.push({ json: { row_type: 'suite', id: '', test_suite: suite, muc_dich: suite, cac_buoc: '', ket_qua_mong_muon: '', ghi_chu: '' } });
  for (const tc of g.list) {
    result.push({
      json: {
        row_type: 'testcase',
        id: '[' + prefix + ']_' + (++tcNo),
        test_suite: suite,
        muc_dich: tc.muc_dich || '',
        cac_buoc: tc.cac_buoc || '',
        ket_qua_mong_muon: tc.ket_qua_mong_muon || '',
        ghi_chu: tc.ghi_chu || ''
      }
    });
  }
}
return result;

// Chia dữ liệu requirement thành các chunk theo feature (đúng thứ tự tiến trình nghiệp vụ)
// để mỗi lần gọi AI chỉ xử lý 1 nhóm nhỏ -> không bị cắt cụt/rút gọn, coverage chi tiết hơn.
const s = $input.first().json;
const arr = k => (Array.isArray(s[k]) ? s[k] : []);
const MAX_REQ = 6; // số requirement tối đa trong 1 chunk
const BIG = 1e6;
const num = v => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v)) ? BIG : Number(v));
const low = x => String(x === null || x === undefined ? '' : x).toLowerCase().trim();
const pad = n => String(n).padStart(2, '0');
const flat = v => (Array.isArray(v) ? v : v ? [v] : []).map(low).filter(x => x.length >= 2);
const fuzzy = (a, b) => a && b && a.length >= 2 && b.length >= 2 && (a.includes(b) || b.includes(a));
const anyFuzzy = (text, names) => names.some(n => fuzzy(low(text), n));
// Lọc theo tên; nếu không khớp gì và danh sách nhỏ thì lấy hết
function pick(list, textOf, names, cap) {
  if (!list.length) return [];
  const hit = names.length ? list.filter(x => anyFuzzy(textOf(x), names)) : [];
  if (hit.length) return hit;
  return list.length <= cap ? list : [];
}

const requirements = arr('requirements');
if (!requirements.length) throw new Error('Không có requirement để chia chunk.');

// 1. Sắp xếp feature theo flow_order (tiến trình nghiệp vụ), ổn định theo thứ tự xuất hiện
let features = arr('features').map((f, i) => ({ ...f, _i: i }));
features.sort((a, b) => (num(a.flow_order) - num(b.flow_order)) || (a._i - b._i));
const known = new Set(features.map(f => f.feature_id));
const orphans = requirements.filter(r => !known.has(r.feature_id));
if (orphans.length) {
  features.push({
    feature_id: '__GENERAL__',
    feature_name: features.length ? 'Yêu cầu chung' : (orphans[0].type || 'Yêu cầu chung'),
    description: '', flow_order: BIG, _i: BIG
  });
}
const suiteNames = features.map(f => f.feature_name);

const changeScope = s.change_scope || { changed: [], unchanged_but_impacted: [] };
const baseCtx = {
  all_suites_in_order: suiteNames,
  change_scope: changeScope,
  dependencies: arr('dependencies').slice(0, 30)
};

function buildContext(feature, reqs) {
  const ids = new Set(reqs.map(r => r.requirement_id));
  const names = [].concat(...reqs.map(r => flat(r.related_fields)));
  const apis = [].concat(...reqs.map(r => flat(r.related_api)));
  const sts = [].concat(...reqs.map(r => flat(r.related_state)));
  const byReq = x => ids.has(x.requirement_id);
  return {
    ...baseCtx,
    feature,
    requirements: reqs,
    business_rules: arr('business_rules').filter(byReq),
    decision_tables: arr('decision_tables').filter(byReq),
    integrations: arr('integrations').filter(byReq),
    exceptions: arr('exceptions').filter(byReq),
    flows: arr('flows').filter(f => f.feature_id === feature.feature_id),
    inputs: pick(arr('inputs'), x => x.name, names, 20),
    apis: pick(arr('apis'), x => x.name, apis, 15),
    data_objects: pick(arr('data_objects'), x => (x.table_or_object || '') + ' ' + (x.field || ''), names.concat(sts), 20),
    states: pick(arr('states'), x => (x.entity || '') + ' ' + (x.state || ''), sts.concat(names), 20),
    ambiguities: arr('ambiguities').filter(a => ids.has(a.related_requirement_id))
  };
}

const out = [];
features.forEach((f, idx) => {
  const reqs = requirements.filter(r =>
    f.feature_id === '__GENERAL__' ? !known.has(r.feature_id) : r.feature_id === f.feature_id);
  if (!reqs.length) return;
  const parts = Math.ceil(reqs.length / MAX_REQ);
  for (let p = 0; p < parts; p++) {
    const slice = reqs.slice(p * MAX_REQ, (p + 1) * MAX_REQ);
    const feature = { feature_id: f.feature_id, feature_name: f.feature_name, description: f.description || '' };
    out.push({
      json: {
        chunk_id: 'F' + pad(idx + 1) + (parts > 1 ? '-' + (p + 1) : ''),
        suite_name: f.feature_name,
        suite_order: idx + 1,
        part: p + 1,
        total_parts: parts,
        context: buildContext(feature, slice)
      }
    });
  }
});

// 2. Chunk hồi quy riêng nếu tài liệu có phạm vi thay đổi mà chưa có feature hồi quy
const hasRegression = features.some(f => /hồi quy|regression/i.test(f.feature_name || ''));
const csHas = (changeScope.changed || []).length || (changeScope.unchanged_but_impacted || []).length;
if (csHas && !hasRegression) {
  const order = features.length + 1;
  out.push({
    json: {
      chunk_id: 'F' + pad(order),
      suite_name: 'Hồi quy các luồng bị ảnh hưởng bởi thay đổi',
      suite_order: order,
      part: 1,
      total_parts: 1,
      context: {
        ...baseCtx,
        feature: { feature_id: '__REGRESSION__', feature_name: 'Hồi quy các luồng bị ảnh hưởng bởi thay đổi', description: 'Các luồng đi qua API/module bị thay đổi phải giữ nguyên hành vi cũ.' },
        requirements: requirements.map(r => ({
          requirement_id: r.requirement_id, type: r.type, requirement: r.requirement,
          expected_behavior: r.expected_behavior, preconditions: r.preconditions,
          related_api: r.related_api, related_fields: r.related_fields, related_state: r.related_state
        })),
        business_rules: arr('business_rules'),
        decision_tables: [],
        integrations: arr('integrations'),
        exceptions: [],
        flows: arr('flows'),
        inputs: [],
        apis: arr('apis'),
        data_objects: arr('data_objects').slice(0, 30),
        states: arr('states').slice(0, 30),
        ambiguities: []
      }
    }
  });
}

if (!out.length) throw new Error('Không tạo được chunk nào từ dữ liệu requirement.');
return out;

