// Group test conditions into batches; each batch = 1 AI call.
// The AI node then processes the batches IN PARALLEL (see its Batch Processing option) instead of a serial loop.
const SIZE = 4; // conditions per AI call
const conds = $input.all().map(i => i.json.conditions).filter(Boolean);
if (!conds.length) return [];
const out = [];
for (let i = 0; i < conds.length; i += SIZE) {
  out.push({ json: { batch_no: out.length + 1, conditions: conds.slice(i, i + SIZE) } });
}
return out;

// Chia tài liệu thành các phần nhỏ gọn để AI phản hồi nhanh (< 30s/chunk).
// Giảm CHUNK_CHARS xuống 2000 ký tự (khoảng 1.200 - 1.500 tokens) giúp Viettel AI xử lý cực mượt.
const CHUNK_CHARS = 5000;

const src = $input.first().json;
const text = String(src.data || '').trim();
if (!text) throw new Error('Tài liệu rỗng, không có gì để chia chunk.');

// Tên/tiêu đề tài liệu: gắn vào đầu mỗi chunk để AI không mất ngữ cảnh
const docTitle = String(src['Bài toán'] || '').trim() || text.slice(0, 120).split('\n')[0];

// Lọc bỏ dữ liệu rác/hình ảnh nặng không dùng đến để tránh làm phình Payload truyền sang AI
const sanitizedSrc = { ...src };
delete sanitizedSrc.doc_images;
delete sanitizedSrc.doc_image_count;

// 1. Tách thành các "đoạn" nhỏ (dòng); dòng quá dài thì cắt tiếp theo câu/độ dài
const SEP = '--- TÀI LIỆU TIẾP THEO ---';
const pieces = [];
for (const line of text.split('\n')) {
  if (line.length <= CHUNK_CHARS) { pieces.push(line); continue; }
  let rest = line;
  while (rest.length > CHUNK_CHARS) {
    let cut = rest.lastIndexOf('. ', CHUNK_CHARS);
    if (cut < CHUNK_CHARS * 0.5) cut = rest.lastIndexOf(' ', CHUNK_CHARS);
    if (cut < CHUNK_CHARS * 0.5) cut = CHUNK_CHARS;
    pieces.push(rest.slice(0, cut + 1).trim());
    rest = rest.slice(cut + 1);
  }
  if (rest.trim()) pieces.push(rest.trim());
}

// 2. Gom các đoạn thành chunk <= CHUNK_CHARS; ưu tiên ngắt tại dấu phân cách giữa các tài liệu
const chunks = [];
let cur = '';
for (const p of pieces) {
  const isSep = p.trim() === SEP;
  if (cur && (cur.length + p.length + 1 > CHUNK_CHARS || (isSep && cur.length > CHUNK_CHARS * 0.4))) {
    chunks.push(cur.trim());
    cur = '';
  }
  if (isSep && !cur) continue;   // không để dấu phân cách ở đầu chunk
  cur += (cur ? '\n' : '') + p;
}
if (cur.trim()) chunks.push(cur.trim());

const total = chunks.length;
return chunks.map((c, i) => ({
  json: {
    ...sanitizedSrc,
    data: (total > 1 ? '[Tài liệu: ' + docTitle + ' | Phần ' + (i + 1) + '/' + total + ']\n' : '') + c,
    chunk_index: i + 1,
    total_chunks: total,
    is_last_chunk: i === total - 1
  },
  pairedItem: { item: 0 }
}));

// Dựng text từ Google Docs API: giữ tiêu đề, danh sách, BẢNG (dạng "cột1 | cột2") và vị trí ẢNH.
// Gắn lại các field của bài toán (Bài toán, URL, ...) vì node HTTP không giữ field đầu vào.
const srcItems = $('phân_luồng_tài_liệu').all();
const out = [];

function renderParagraph(p, images) {
  let t = '';
  for (const el of (p.elements || [])) {
    if (el.textRun && el.textRun.content) t += el.textRun.content;
    else if (el.inlineObjectElement) {
      images.push({ id: el.inlineObjectElement.inlineObjectId });
      t += ' [HÌNH ' + images.length + ': chưa được đọc] ';
    }
  }
  t = t.replace(/\u000b/g, ' ').replace(/\s+$/g, '');
  if (!t.trim()) return '';
  const st = (p.paragraphStyle && p.paragraphStyle.namedStyleType) || '';
  const m = st.match(/^HEADING_(\d)/);
  if (st === 'TITLE') return '# ' + t.trim();
  if (m) return '#'.repeat(Number(m[1])) + ' ' + t.trim();
  if (p.bullet) return '- ' + t.trim();
  return t.trim();
}

function renderContent(content, images) {
  const lines = [];
  for (const el of (content || [])) {
    if (el.paragraph) {
      const l = renderParagraph(el.paragraph, images);
      if (l) lines.push(l);
    } else if (el.table) {
      lines.push('[BẢNG]');
      for (const row of (el.table.tableRows || [])) {
        const cells = (row.tableCells || []).map(c =>
          renderContent(c.content, images).replace(/\n+/g, ' / ').trim());
        lines.push('| ' + cells.join(' | ') + ' |');
      }
      lines.push('[HẾT BẢNG]');
    }
  }
  return lines.join('\n');
}

$input.all().forEach((it, idx) => {
  const doc = it.json || {};
  if (doc.error) throw new Error('Docs API lỗi: ' + JSON.stringify(doc.error).slice(0, 300));
