  if (!src) src = srcItems[idx];
  const base = src ? src.json : {};

  const images = [];
  const body = (doc.body && doc.body.content) || [];
  const text = renderContent(body, images);

  // Gắn thông tin ảnh để bước đọc ảnh (nếu bổ sung sau này) dùng lại
  const objs = doc.inlineObjects || {};
  const imgInfo = images.map((im, i) => {
    const e = (objs[im.id] || {}).inlineObjectProperties;
    const emb = e && e.embeddedObject;
    return {
      n: i + 1,
      contentUri: emb && emb.imageProperties ? emb.imageProperties.contentUri : null,
      width: emb && emb.size && emb.size.width ? emb.size.width.magnitude : null,
      height: emb && emb.size && emb.size.height ? emb.size.height.magnitude : null
    };
  });

  out.push({ json: { ...base, data: text, doc_title: doc.title || '', doc_image_count: imgInfo.length, doc_images: imgInfo } });
});
return out;

