// Chọn tối đa 4 testcase ĐÃ DUYỆT giống chunk nhất, gắn vào memory_text cho Test_condition_generator
const chunks = $('Split_By_Feature').all();
const mem = $input.all().map(i => i.json).filter(r => r && r.content && r.content.muc_dich);
const norm = s => String(s || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ');
const toks = s => new Set(norm(s).split(/\s+/).filter(w => w.length >= 3));
const memTok = mem.map(r => ({ r, t: toks((r.test_suite || '') + ' ' + (r.problem_title || '') + ' ' + r.content.muc_dich), suite: norm(r.test_suite).trim() }));
return chunks.map(c => {
  let memory_text = '';
  if (memTok.length) {
    const ctx = JSON.stringify(c.json.context || {}).slice(0, 5000);
    const ct = toks((c.json.suite_name || '') + ' ' + ctx);
    const suite = norm(c.json.suite_name).trim();
    const scored = memTok.map(m => {
      let s = 0; m.t.forEach(w => { if (ct.has(w)) s++; });
      if (m.suite && m.suite === suite) s += 5;
      return { m, s };
    }).filter(x => x.s >= 3).sort((a, b) => b.s - a.s);
    const picked = [], seen = new Set();
    for (const x of scored) {
      const k = norm(x.m.r.content.muc_dich).trim();
      if (seen.has(k)) continue; seen.add(k); picked.push(x.m.r);
      if (picked.length >= 4) break;
    }
    memory_text = picked.map((r, i) => (i + 1) + '. [' + (r.problem_title || '') + ' | ' + (r.test_suite || '') + '] ' + r.content.muc_dich
      + '\n   Kết quả: ' + String(r.content.ket_qua_mong_muon || '').replace(/\s+/g, ' ').slice(0, 220)).join('\n');
  }
  return { json: { ...c.json, memory_text } };
});
